function isNight(){ const hour=state.hour===null?new Date().getHours():Number(state.hour); return state.mode==='night' || (state.mode==='auto' && (state.page==='player' && state.audioKind==='sleep' || hour>=19 || hour<7)); }
function ambientLight(hour){
  // Interpolate local hours and minutes instead of jumping between three bands.
  const points=[[0,-34,.34],[7,-34,.46],[11,-8,.25],[16,22,.13],[19,34,.08],[24,34,.08]];
  const h=Math.max(0,Math.min(24,hour));
  const end=points.findIndex(p=>p[0]>=h);
  const b=points[Math.max(1,end)],a=points[Math.max(0,end-1)],mix=(h-a[0])/(b[0]-a[0]);
  return {shift:a[1]+(b[1]-a[1])*mix,opacity:a[2]+(b[2]-a[2])*mix};
}
function applyAmbient(){
  const night=isNight(); document.body.dataset.mode=night?'night':'day';
  const now=new Date(),hour=state.hour===null?now.getHours()+now.getMinutes()/60:Number(state.hour);
  const light=ambientLight(hour);
  document.documentElement.style.setProperty('--sun-shift',light.shift+'%');
  document.documentElement.style.setProperty('--sun-opacity',light.opacity);
  document.getElementById('status-time').textContent=state.hour===null?ewFormatDate(new Date(),{hour:'2-digit',minute:'2-digit'}):String(hour).padStart(2,'0')+':00';
}
