function persist(automatic=false){
 psSavePreferences();if(automatic&&(personalStorage.initializing||personalStorage.blocked||personalStorage.scope===null||personalStorage.switching))return false;
 if(personalStorage.scope===null){if(!automatic)toast(psSaveError());return false;}if(initial.persist===false)return true;
 try{if(!personalStorage.migrationReady&&!psMigrate())throw Error('migration');const token=psToken();localStorage.setItem(psKey(token.scope),JSON.stringify({schema:1,scope:token.scope,data:psSnapshot()}));personalStorage.blocked=false;personalStorage.error='';return true;}
 catch{personalStorage.blocked=true;personalStorage.error=psSaveError();if(!automatic)toast(personalStorage.error);return false;}
}
