 state.wellness={...defaultWellness(),...(data.wellness||{})};for(const key of ['intentions','body','mind'])if(!state.wellness[key]||typeof state.wellness[key]!=='object')state.wellness[key]={};if(!Array.isArray(state.wellness.sessions))state.wellness.sessions=[];if(!Array.isArray(state.wellness.plan))state.wellness.plan=defaultWellness().plan;state.wellness.continuity={checkpoint:null,...(state.wellness.continuity||{})};if(!Array.isArray(state.wellness.continuity.cardActions))state.wellness.continuity.cardActions=[];
 state.daily={checkins:{},draws:{},favorites:[],musicSessions:[],...(data.daily||{})};for(const key of ['checkins','draws'])if(!state.daily[key]||typeof state.daily[key]!=='object')state.daily[key]={};for(const key of ['favorites','musicSessions'])if(!Array.isArray(state.daily[key]))state.daily[key]=[];
 state.support={ai:[],friends:[],messages:{},posts:[],requests:[],...(data.support||{}),preferences};for(const key of ['ai','friends','posts','requests'])if(!Array.isArray(state.support[key]))state.support[key]=[];state.support.profile={name:'',code:'PREVIEW-LOCAL',...(state.support.profile||{})};if(!state.support.messages||typeof state.support.messages!=='object')state.support.messages={};
 state.membership={drafts:[],selected:'advanced',...(data.membership||{})};if(!Array.isArray(state.membership.drafts))state.membership.drafts=[];
 Object.assign(state,{selectedDate:localDate(),practiceKey:'breath',sessionSlot:null,lastSession:null,audioSeconds:0,audioTotal:60,audioPlaying:false,playerEnded:false,audioReturn:'home',traitDraft:{...(state.daily.traits?.answers||{})},ziweiDraft:null,ziweiResult:null,ziweiEditing:true,ziweiError:'',ziweiCacheKey:'',profileNameDraft:null,profileAvatarDraft:state.support.profile.avatar||'mind',ssChatId:null,ssAttachment:null,ssPostText:'',ssAiContext:null,ssFriendQuery:'',ssFriendSearched:false,ssRequestId:null,ssRequestDraft:null,memberDraftId:null,growthRange:'7',journeyType:'all',cardDate:today(),checkinDate:today()});
