const screens={home,onboard,gate,body,mind,lifeResult,portrait,wisdom,service,profile,course,consult,player,splash};
let ambientTransition=null,renderSequence=0;
function render(resetScroll=true){
 const sequence=++renderSequence;
 if(ambientTransition){ambientTransition.skipTransition();ambientTransition=null;}
 const changed=document.body.dataset.mode && document.body.dataset.mode!==(isNight()?'night':'day');
 if(changed && document.startViewTransition && !matchMedia('(prefers-reduced-motion: reduce)').matches){
  document.documentElement.dataset.ambientTransition='true';
  const transition=document.startViewTransition(()=>{if(sequence===renderSequence)renderNow(resetScroll);});
  ambientTransition=transition;
  transition.ready.catch(()=>{});
  transition.finished.catch(()=>{}).finally(()=>{
   if(ambientTransition===transition){ambientTransition=null;delete document.documentElement.dataset.ambientTransition;}
  });
  return transition.updateCallbackDone;
 }
 delete document.documentElement.dataset.ambientTransition;
 renderNow(resetScroll);
 return Promise.resolve();
}
function renderNow(resetScroll=true){
 if(!screens[state.page])state.page='home';
 const app=document.getElementById('app');const oldTop=app.scrollTop;document.documentElement.lang=ewI18n.locales[state.lang].tag;document.body.dataset.page=state.page;
 applyAmbient();app.innerHTML=screens[state.page]();
 // Do not restart the entry animation when the scene-transition marker clears.
 if(document.documentElement.dataset.ambientTransition)app.firstElementChild.style.animation='none';
 const active=['home','timeline','wisdom','profile'].includes(state.page)?state.page:['gate','body','mind','lifeResult'].includes(state.page)?'gate':['lifeReview','bodyHistory','mindHistory','portrait','advanced','advancedPlan','course','consult'].includes(state.page)?'profile':'home';
 document.getElementById('nav').innerHTML=[['home','home',t('Today','今日')],['gate','compass',t('Maps','地图')],['timeline','clock',t('Rhythm','时间轴')],['wisdom','book',t('Practice','练习')],['profile','user',t('You','我的')]].map(([id,i,n])=>`<button data-action="go" data-to="${id}" class="${active===id?'selected':''}" ${active===id?'aria-current="page"':''}>${icon(i)}<span>${n}</span></button>`).join('');
 app.scrollTop=resetScroll?0:oldTop;
 persist(true);noticeParent();
}
