let audioContext=null,audioGain=null,audioOsc=[],audioTimer=null,audioLast=0,volumeValue=.3,audioGeneration=0;
function formatTime(n){return Math.floor(n/60)+':'+String(Math.floor(n)%60).padStart(2,'0');}
async function startAudio(){
 const token=psToken(),generation=++audioGeneration;if(!token.scope)return;try{
  if(!audioContext){audioContext=new (window.AudioContext||window.webkitAudioContext)();}
  await audioContext.resume();if(!psCurrent(token)||generation!==audioGeneration||state.page!=='player')return;
  audioGain=audioContext.createGain();audioGain.gain.value=0;audioGain.connect(audioContext.destination);
  [196,294].forEach((freq,i)=>{const osc=audioContext.createOscillator();const gain=audioContext.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.value=i?.23:.5;osc.connect(gain);gain.connect(audioGain);osc.start();audioOsc.push(osc);});
  if(state.audioSeconds>=state.audioTotal)state.audioSeconds=0;
  state.audioPlaying=true;state.playerEnded=false;audioLast=performance.now();
  audioGain.gain.setTargetAtTime(volumeValue*.12,audioContext.currentTime,.4);
  render(false);tickAudio();audioTimer=setInterval(tickAudio,100);
 }catch{if(!psCurrent(token)||generation!==audioGeneration)return;stopAudio();toast(t('Audio is unavailable. You can read the practice transcript.','音频不可用，可以阅读练习引导文字。'));}
}
function stopAudio(){
 ++audioGeneration;clearInterval(audioTimer);audioTimer=null;state.audioPlaying=false;
 if(audioGain&&audioContext){const gain=audioGain,osc=audioOsc;gain.gain.setTargetAtTime(0,audioContext.currentTime,.1);setTimeout(()=>{osc.forEach(o=>{try{o.stop();o.disconnect();}catch{}});gain.disconnect();},450);}
 audioOsc=[];audioGain=null;
}
function tickAudio(){
 if(!state.audioPlaying)return;const now=performance.now();state.audioSeconds+=Math.min((now-audioLast)/1000,1);audioLast=now;
 const phase=state.audioSeconds%8;const v=(.25+.75*(1-Math.cos(phase/8*Math.PI*2))/2)*volumeValue*.12;
 if(audioGain)audioGain.gain.setTargetAtTime(v,audioContext.currentTime,.2);
 const progress=document.getElementById('audio-progress');if(progress)progress.style.width=Math.min(100,state.audioSeconds/state.audioTotal*100)+'%';
 const tm=document.getElementById('audio-time');if(tm)tm.textContent=formatTime(state.audioSeconds);
 const ph=document.getElementById('breath-phase');if(ph)ph.textContent=phase<4?t('Breathe in','轻轻吸气'):t('Breathe out','慢慢呼气');
 document.querySelector('[role=progressbar]')?.setAttribute('aria-valuenow',String(Math.floor(state.audioSeconds)));
 if(state.audioSeconds>=state.audioTotal){state.audioSeconds=state.audioTotal;stopAudio();state.playerEnded=true;render(false);toast(t('This practice is complete. Take a moment before moving on.','本次练习已结束，再给自己一点停留。'));}
}
function openAudio(kind){stopAudio();state.audioReturn=state.page==='player'?state.audioReturn:state.page;state.audioKind=kind;state.audioSeconds=0;state.audioTotal=60;state.page='player';render();}
function transcript(){sheet(t('A breathing pause','一段呼吸停顿'),`<p>${t('Find a comfortable position. Allow your shoulders to soften. Notice one natural breath as it comes and goes. If your attention wanders, gently return to the next breath. There is no need to hold or force your breath.','找一个舒适的姿势，让肩膀自然放松。觉察一次自然呼吸的来去。如果注意力游离，轻轻回到下一次呼吸。不需要屏息，也不强求节奏。')}</p><p>${t('The sample tone rises and falls over eight seconds. Follow it only if the rhythm feels comfortable; your own breathing comes first.','示例提示音每八秒起伏一次。仅在舒适时跟随，优先保持自己的呼吸节奏。')}</p>`,button(t('Back to the sound','回到声音'),'close-sheet','','secondary full'));}
document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-action]');if(!el)return;
 const action=el.dataset.action;
 if(action==='go')navigate(el.dataset.to);
 else if(action==='need'){state.need=el.dataset.value;if(state.need==='sleep'||state.need==='habit')state.domain='body';render(false);}
 else if(action==='domain'){state.domain=el.dataset.value;render(false);}
 else if(action==='recommend'){if(!persist())return;navigate({sleep:'body',self:'lifeResult',wisdom:'wisdom',habit:'mind'}[state.need]);toast(t('A starting point chosen from your interests.','已根据你的选择推荐起点。'));}
 else if(action==='ambient')ambientSheet();
 else if(action==='set-mode'){state.mode=el.dataset.value;render(false);ambientSheet();}
 else if(action==='close-sheet')closeSheet();
 else if(action==='term')showTerm(el.dataset.term);
 else if(action==='answers')showAnswers(el.dataset.return);
 else if(action==='save-answers'){const f=document.getElementById('answer-form');if(!psCommit(()=>{state.answers=Object.fromEntries(new FormData(f));state.hasAnswers=true;}))return;closeSheet();navigate(el.dataset.return);toast(t('Your answers and recommendations have been updated.','已更新你的回答与建议。'));}
 else if(action==='save-life'){const strength=document.getElementById('strength-note').value.trim();const direction=document.getElementById('direction-note').value.trim();if(!strength&&!direction){toast(t('Add a reflection before saving.','请先填写一项自己的观察。'));return;}if(!psCommit(()=>{state.lifeNotes={strength,direction};}))return;closeSheet();render(false);showLifeNotes();}
 else if(action==='life-notes')showLifeNotes();
 else if(action==='journal'){const txt=document.getElementById('journal').value.trim();if(!txt){document.getElementById('journal-note').textContent=t('Add a thought before saving.','请先写下一点想法。');return;}if(psCommit(()=>{state.journal=txt;}))document.getElementById('journal-note').textContent=t('Saved in this browser.','已保存在本浏览器。');else document.getElementById('journal-note').textContent=psSaveError();}
 else if(action==='audio')openAudio(el.dataset.kind||'practice');
 else if(action==='toggle-audio'){if(state.audioPlaying){stopAudio();render(false);}else await startAudio();}
 else if(action==='restart-audio'){stopAudio();state.audioSeconds=0;render(false);await startAudio();}
 else if(action==='transcript')transcript();
 else if(action==='close-player'){if(typeof journeyCheckpoint==='function')journeyCheckpoint();stopAudio();navigate(state.audioReturn);}
 else if(action==='finish'){stopAudio();if(!psCommit(()=>{state.completed=true;state.user='returning';}))return;navigate('profile');toast(t('Practice saved. Thank you for taking this moment.','已记录本次练习，记得把这份从容带回日常。'));}
 else if(action==='course'){currentCourse=['199','349','499'].includes(el.dataset.course)?el.dataset.course:currentCourse;navigate('course');}
 else if(action==='locked')purchaseSheet();
 else if(action==='purchase')purchaseSheet();
 else if(action==='confirm-purchase'){if(!document.getElementById('purchase-ack').checked){document.getElementById('purchase-error').textContent=t('Please acknowledge that this is a preview.','请先确认这是流程预览。');return;}sheet(t('Purchase preview complete','购买流程预览完成'),`<p>${t('The confirmation step is ready for review. No payment was processed and no course access was issued.','确认步骤已演示完成。未处理付款，也未开通课程权限。')}</p>`,button(t('Back to course','返回课程'),'close-sheet','','full'));}
 else if(action==='save'){if(!psCommit(()=>{state.savedCourse=!state.savedCourse;}))return;render(false);toast(state.savedCourse?t('Course saved.','课程已收藏。'):t('Course removed from saved.','已取消收藏。'));}
 else if(action==='consult-type'){state.consultType=el.dataset.value;state.slot='';render(false);}
 else if(action==='slot'){state.slot=el.dataset.value;document.querySelectorAll('.time-slots button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.value===state.slot));}
 else if(action==='booking'){
  const date=document.getElementById('session-date').value;const valid=document.getElementById('session-date').checkValidity();
  if(!state.slot||!date||!valid){document.getElementById('booking-error').textContent=t('Choose a valid date and sample time to continue.','请选择有效日期与示例时间，再继续。');return;}
  sheet(t('Review your session','确认咨询信息'),`<div class="receipt"><strong>${state.consultType==='expert'?t('1:1 expert session','专家 1 对 1 咨询'):t('AI-guided session','AI 引导会谈')}</strong><p>${esc(date)} · ${esc(state.slot)}<br>${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}<br>USD $150 / ${t('session','次')}</p></div><p>${t('This is a sample date and price. Provider, duration, taxes and cancellation terms need confirmation. No live reservation or payment will be created.','日期与价格为示例。服务方、会谈时长、税费与取消条款待确认。不会创建实际预约或付款。')}</p>`,button(t('Complete booking preview','完成预约流程预览'),'confirm-booking','','full'));
 }
 else if(action==='confirm-booking')sheet(t('Booking preview complete','预约流程预览完成'),`<p>${t('The review flow is complete. No real appointment was reserved.','已完成预约确认流程演示，未创建真实预约。')}</p>`,button(t('Return','返回'),'close-sheet','','full'));
 else if(action==='billing'){state.billing=el.dataset.value;render(false);}
 else if(action==='terms')sheet(t('Subscription terms','订阅说明'),`<p>${t('Proposed: monthly or annual billing in USD, automatically renewing each period. Cancel before the next renewal to stop future charges. The final price, AI usage limits, taxes and refund rules must be approved and displayed before checkout.','拟定：以 USD 按月或按年订阅，每周期自动续费；下次续费前取消可停止后续扣款。最终价格、AI 额度、税费与退款规则需业务批准并在购买前展示。')}</p><p>${t('Courses, expert / AI sessions and retreats are paid separately. There is no active subscription purchase in this prototype.','课程、专家 / AI 会谈和静修活动均另外收费。此原型未开通实际订阅购买。')}</p>`,button(t('Understood','了解了'),'close-sheet','','secondary full'));
 else if(action==='reading')sheet(t('Reading in context','带着背景阅读'),`<p>${t('This collection introduces the Diamond Sutra in its Mahāyāna Buddhist context. It separates scripture passages, commentary and modern reflections. Verified editions and expert-reviewed course material will be added before release.','本领域在大乘佛教语境中介绍《金刚经》，区分经典原文、注解和现代感悟。正式上线前需补充经核实的版本及专业审阅内容。')}</p>`,button(t('Return to the collection','返回内容领域'),'close-sheet','','secondary full'));
 else if(action==='checkin'){if(!psCommit(()=>{state.checkedIn=true;}))return;render(false);toast(t('Today’s check-in is saved.','已记录今日签到。'));}
 else if(action==='saved'){if(state.savedCourse)navigate('course');else sheet(t('Your saved collection','我的收藏'),`<div class="empty-state">${icon('bookmark','icon-lg')}<p>${t('Save a course to return to it here.','收藏课程后，就可以在这里找到它。')}</p></div>`,go(t('Explore courses','浏览课程'),'course','full'));}
 else if(action==='orders')sheet(t('Orders & sessions','订单与咨询'),`<div class="empty-state">${icon('calendar','icon-lg')}<p>${t('There are no real orders or bookings in this design preview.','设计预览中尚无真实订单或预约。')}</p></div>`,go(t('Explore sessions','了解咨询'),'consult','full'));
 else if(action==='events')sheet(t('Retreats & events','静修与活动'),`<p>${t('Events are booked separately from membership. Dates, locations and prices will be listed when confirmed.','活动在会员之外单独预约。具体日期、地点与价格将在确认后展示。')}</p>`,button(t('Return','返回'),'close-sheet','','secondary full'));
});
function showLifeNotes(){let life=state.lifeNotes||{};try{if(!state.lifeNotes)life={};}catch{}sheet(t('Your own observations','你自己的观察'),`<p><b>${t('A strength I notice','我留意到的优势')}</b><br>${esc(life.strength||t('Not added yet','尚未填写'))}</p><p><b>${t('A direction I choose','我选择的方向')}</b><br>${esc(life.direction||t('Not added yet','尚未填写'))}</p><p class="small">${t('Your words, saved in this browser.','你的原话，保存在本浏览器。')}</p>`,button(t('Continue reflecting','继续探索'),'close-sheet','','full'));}
document.addEventListener('change',e=>{if(e.target.id==='mode-select'){state.mode=e.target.value;render(false);}if(e.target.id==='language-select'){ewChangeLanguage(e.target.value);}});
document.addEventListener('input',e=>{if(e.target.id==='volume'){volumeValue=Number(e.target.value)/100;}});
document.getElementById('sheet').addEventListener('click',e=>{const d=document.getElementById('sheet');if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet();}});
document.getElementById('sheet').addEventListener('close',()=>priorFocus?.focus?.());
window.addEventListener('message',e=>{
 if(e.source!==parent||!e.data||e.data.type!=='ew-settings')return;
 const d=e.data;if(['en','zh','zh-Hant','bo','zh-Hans','zh-CN','zh-TW'].includes(d.lang))state.lang=ewI18n.normalize(d.lang);if(['auto','day','night'].includes(d.mode))state.mode=d.mode;if(['new','returning'].includes(d.user))state.user=d.user;if(d.hour===null||Number.isInteger(d.hour)&&d.hour>=0&&d.hour<24)state.hour=d.hour;
 if(d.reset){stopAudio();state.hasAnswers=false;state.answers={sleep:'restless',energy:'low',stress:'high',comfort:'tense'};state.completed=false;state.checkedIn=false;state.savedCourse=false;state.domain='body';state.need='sleep';state.page='home';}
 if(screens[d.page]){if(state.page==='player'&&d.page!=='player')stopAudio();if(d.page==='player'&&state.page!=='player'){state.audioKind='sleep';state.audioReturn=state.page;}state.page=d.page;}
 closeSheet();render();
});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.audioPlaying){stopAudio();if(state.page==='player')render(false);}});
// Native summary click also covers touch and keyboard activation.
document.addEventListener('click',e=>{
 const summary=e.target.closest('summary');if(!summary)return;
 const detail=summary.parentElement;if(detail.tagName!=='DETAILS')return;
 e.preventDefault();
 const expand=detail.dataset.expanded===undefined?!detail.open:detail.dataset.expanded!=='true';
 const from=detail.getBoundingClientRect().height/(detail.classList.contains('is-expanded')?1.01:1);
 const transform=getComputedStyle(detail).transform;
 detail._expansion?.cancel();detail.dataset.expanded=String(expand);
 summary.setAttribute('aria-expanded',String(expand));
 detail.style.height='';detail.open=true;
 const full=detail.offsetHeight;
 detail.open=false;const closed=detail.offsetHeight;detail.open=true;
 const finish=()=>{detail.open=expand;detail.style.height='';detail.classList.toggle('is-expanded',expand);};
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){finish();return;}
 detail.style.height=from+'px';
 const animation=detail.animate([
  {height:from+'px',transform:transform==='none'?'scale(1)':transform},
  {height:(expand?full:closed)+'px',transform:expand?'scale(1.01)':'scale(1)'}
 ],{duration:300,easing:'cubic-bezier(.2,.75,.25,1)',fill:'forwards'});
 detail._expansion=animation;
 animation.finished.then(()=>{if(detail._expansion===animation){finish();animation.cancel();detail._expansion=null;}}).catch(()=>{});
});
setInterval(()=>{
 const next=isNight()?'night':'day';
 if(document.body.dataset.mode!==next)render(false);else applyAmbient();
},60000);
